ValidationRule.errorConditionFormula:
AND(
NOT($RecordType.Name = 'IVF Treatment'),
ISPICKVAL(AreYouAGestationalCarrier__c, "Yes"),
ISPICKVAL(ExceptionRequest__c, "No"),
OR(
ISNEW(),
ISCHANGED(Applicant1DateOfBirth__c),
AND(ISCHANGED(Status), ISPICKVAL(Status,"Approved"))
),
OR(
ISBLANK(Applicant1DateOfBirth__c),
/* Age < 18 */
(
(YEAR(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) - YEAR(Applicant1DateOfBirth__c)) -
IF(
OR(
MONTH(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) < MONTH(Applicant1DateOfBirth__c),
AND(
MONTH(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) = MONTH(Applicant1DateOfBirth__c),
DAY(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) < DAY(Applicant1DateOfBirth__c)
)
),
1,
0
)
) < 18,

/* Status = Approved AND Age > 42 */
AND(
ISPICKVAL(Status, "Approved"),
(
(YEAR(DateOfApplicationSubmission__c) - YEAR(Applicant1DateOfBirth__c)) -
IF(
OR(
MONTH(DateOfApplicationSubmission__c) < MONTH(Applicant1DateOfBirth__c),
AND(
MONTH(DateOfApplicationSubmission__c) = MONTH(Applicant1DateOfBirth__c),
DAY(DateOfApplicationSubmission__c) < DAY(Applicant1DateOfBirth__c)
)
),
1,
0
)
) > 42
),

/* Status ≠ Approved AND Age > 41 */
AND(
NOT(ISPICKVAL(Status, "Approved")),
(
(YEAR(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) - YEAR(Applicant1DateOfBirth__c)) -
IF(
OR(
MONTH(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) < MONTH(Applicant1DateOfBirth__c),
AND(
MONTH(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) = MONTH(Applicant1DateOfBirth__c),
DAY(IF(ISBLANK(DateOfApplicationSubmission__c), TODAY(), DateOfApplicationSubmission__c)) < DAY(Applicant1DateOfBirth__c)
)
),
1,
0
)
) > 41
)
)
)
